UPDATE campus_account
platform = #{platform}, account_name = #{accountName}, account_uid = #{accountUid}, homepage_url = #{homepageUrl}, account_type = #{accountType}, related_person_desc = #{relatedPersonDesc}, related_department_id = #{relatedDepartmentId}, source_basis = #{sourceBasis}, task_no = #{taskNo}, authorization_scope = #{authorizationScope}, focus_start_time = #{focusStartTime}, focus_end_time = #{focusEndTime}, focus_level = #{focusLevel}, responsible_department_id = #{responsibleDepartmentId}, responsible_user_id = #{responsibleUserId}, tags = #{tags}, remark = #{remark}, update_user_id = #{updateUserId}
WHERE account_id = #{accountId} AND deleted = 0

UPDATE campus_account
SET account_status = #{accountStatus},
    update_user_id = #{updateUserId}
WHERE account_id = #{accountId}
  AND deleted = 0

UPDATE campus_account
SET deleted = 1,
    update_user_id = #{updateUserId}
WHERE account_id = #{accountId}
  AND deleted = 0

mapper.select:
SELECT 
FROM campus_account
WHERE deleted = 0

    AND (
        account_name LIKE CONCAT('%', #{keyword}, '%')
        OR account_uid LIKE CONCAT('%', #{keyword}, '%')
        OR homepage_url LIKE CONCAT('%', #{keyword}, '%')
        OR tags LIKE CONCAT('%', #{keyword}, '%')
    )


    AND platform = #{platform}


    AND focus_level = #{focusLevel}


    AND audit_status = #{auditStatus}


    AND account_status = #{accountStatus}


    AND focus_end_time <= #{focusEndBefore}

ORDER BY update_time DESC, id DESC

SELECT COUNT(1)
FROM campus_account
WHERE platform = #{platform}
  AND account_uid = #{accountUid}
  AND deleted = 0

    AND account_id != #{excludeAccountId}
